//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::libm::cbrtf`; the
//! native twin is `benches/native/Bench/LibmCbrtf.lean`.

#![allow(
    unused_parens,
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]

use lean_runtime::semantics::{float32, libm};
use lean_runtime_bench::{run, step, SEED};

#[allow(unused_variables)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0.0f32);
    for _ in 0..n {
        x = step(x);
        acc += libm::cbrtf(
            ((-1048576.0 + ((x >> 11) as f64 * (1.0 / 9007199254740992.0)) * 2097152.0) as f32),
        );
    }
    float32::to_bits(acc) as u64
}

fn main() {
    run(|| (), kernel)
}
